"use strict";const e=require("./api.js");exports.createRole=async function(t){return e.request({path:"/roles",method:"POST",data:{name:t}})},exports.deleteRole=async function(t){return e.request({path:`/roles/${t}`,method:"DELETE"})},exports.fetchRoles=async function(){return e.request({path:"/roles"})},exports.updateRole=async function(t,r){return e.request({path:`/roles/${t}`,method:"PUT",data:{name:r}})};
